38	export async function deleteCommand(
39		deleteArgs: StrictYargsOptionsToInterface<typeof deleteYargs>,
40		_config: Config
41	) {
42		// API gateway has path restrictions so if someone provides a string that isn't ID shaped, we get a weird error instead of a 404
43		const uuidRegex =
44			/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
45		if (!uuidRegex.test(deleteArgs.ID)) {
46			throw new UserError(
47				`Expected a container ID but got ${deleteArgs.ID}. Use \`wrangler containers list\` to view your containers and corresponding IDs.`
48			);
49		}
50	
51		startSection("Delete your container");
52	
53		if (!isNonInteractiveOrCI()) {
54			const yes = await inputPrompt({
55				question:
56					"Are you sure that you want to delete these containers? The associated DO container will lose access to the containers.",
57				type: "confirm",
58				label: "",
59			});
60			if (!yes) {
61				cancel("The operation has been cancelled");
62				return;
63			}
64		}
65	
66		try {
67			await ApplicationsService.deleteApplication(deleteArgs.ID);
68		} catch (err) {
69			if (!(err instanceof Error)) {
70				throw err;
71			}
72	
73			if (err instanceof ApiError) {
74				if (err.status === 400 || err.status === 404) {
75					throw new UserError(
76						`There has been an error deleting the container.\n${err.body.error}`
77					);
78				}
79	
80				throw new Error(
81					`There has been an unknown error deleting the container.\n${JSON.stringify(err.body)}`
82				);
83			}
84	
85			throw new Error(
86				`There has been an internal error deleting your containers.\n${err.message}`
87			);
88		}
89	
90		endSection("Your container has been deleted");
91	}
