153	async function listCommandHandle(
154		_args: StrictYargsOptionsToInterface<typeof listYargs>,
155		_config: Config
156	) {
157		const keepListIter = true;
158		while (keepListIter) {
159			logRaw(gray(shapes.bar));
160			const { start, stop } = spinner();
161			start("Loading Containers");
162			const [applications, err] = await wrap(
163				ApplicationsService.listApplications()
164			);
165			stop();
166			if (err) {
167				throw new UserError(
168					`There has been an internal error listing your containers.\n ${err.message}`
169				);
170			}
171	
172			// If we don't get multiple applications for any reason exit
173			if (
174				applications === undefined ||
175				applications === null ||
176				applications.length === 0
177			) {
178				logRaw(
179					"No containers found. See https://dash.cloudflare.com/?to=/:account/workers/containers to learn more."
180				);
181				return;
182			}
183	
184			const applicationDetails = (a: Application) => {
185				return {
186					label: `${a.name} (${a.created_at})`,
187					details: YAML.stringify(a).split("\n"),
188					value: a.id,
189				};
190			};
191	
192			const application = await listContainersAndChoose(applications);
193	
194			let refresh = false;
195			await inputPrompt({
196				type: "list",
197				question: "Containers",
198				helpText: "Hit enter to return to your containers or 'r' to refresh",
199				options: [applicationDetails(application)],
200				label: "going back",
201				onRefresh: async () => {
202					start("Refreshing application");
203					const app = await ApplicationsService.getApplication(application.id);
204					if (refresh) {
205						return [];
206					}
207					stop();
208					if (app) {
209						const details = applicationDetails(app);
210						details.label += ", last refresh: " + new Date().toLocaleString();
211						return [details];
212					}
213					return app;
214				},
215			});
216			refresh = true;
217			stop();
218		}
219	}
