18	type ContainerState =
19		| "provisioning"
20		| "running"
21		| "failed"
22		| "stopping"
23		| "stopped"
24		| "unhealthy"
25		| "inactive"
26		| "unknown";
27	
28	function deriveInstanceState(
29		instance: DashApplicationInstance
30	): ContainerState {
31		const status = instance.current_placement?.status;
32		if (!status) {
33			return "unknown";
34		}
35	
36		const raw = status.container_status ?? status.health;
37		switch (raw) {
38			case "placed":
39				return "provisioning";
40			case "running":
41			case "failed":
42			case "stopping":
43			case "stopped":
44			case "unhealthy":
45				return raw;
46			default:
47				return "unknown";
48		}
49	}
50	
51	function colorState(state: ContainerState): string {
52		switch (state) {
53			case "running":
54				return green(state);
55			case "failed":
56			case "unhealthy":
57			case "stopped":
58			case "stopping":
59				return red(state);
60			default:
61				return state;
62		}
63	}
